use bevy::prelude::*;
use bevy_egui::{egui,EguiContexts,EguiPlugin,EguiPrimaryContextPass};
#[derive(Resource,Default)] struct HudInput([f32;2],bool,bool);
use forge_engine::{Project,Simulation,project_point};
use std::path::PathBuf;
#[derive(Resource)] struct Game{project:Project,sim:Simulation,original:Project,demo:Option<forge_engine::DemoSession>,root:PathBuf,level:usize,menu:bool,campaign:bool,finished:bool}
#[derive(Component)] struct ObjectId(uuid::Uuid);
fn main(){if std::env::args().nth(1).as_deref()==Some("--benchmark"){let path=std::env::args_os().nth(2).map(PathBuf::from).unwrap_or_else(||PathBuf::from("examples/signal_lost/project.forge.json"));match forge_engine::performance::benchmark(&path,600){Ok(report)=>{println!("{report}");return;},Err(e)=>{eprintln!("{e}");std::process::exit(1);}}}if std::env::args().nth(1).as_deref()==Some("--smoke"){let path=std::env::args_os().nth(2).map(PathBuf::from).unwrap_or_else(||PathBuf::from("examples/signal_lost/project.forge.json"));match Project::load(&path).and_then(|p|{forge_engine::modules::validate(&p)?;forge_engine::smoke(p)}){Ok(())=>{println!("SMOKE PASS");return;},Err(e)=>{eprintln!("SMOKE FAIL: {e}");std::process::exit(1);}}}let path=std::env::args_os().nth(1).map(PathBuf::from).unwrap_or_else(||PathBuf::from("project.forge.json"));let path=match path.canonicalize(){Ok(p)=>p,Err(e)=>{eprintln!("Project: {e}");std::process::exit(1);}};let p=match Project::load(&path){Ok(p)=>p,Err(e)=>{eprintln!("{e}");std::process::exit(1);}};if let Err(e)=forge_engine::modules::validate(&p){eprintln!("{e}");std::process::exit(1); }let folder=path.parent().unwrap().to_path_buf();let root=folder.to_string_lossy().into_owned();let campaign=folder.join("level2.forge.json").is_file() && folder.join("level3.forge.json").is_file() && path.file_name().is_some_and(|n|n=="project.forge.json");App::new().insert_resource(Game{project:p.clone(),sim:Simulation::default(),original:p.clone(),demo:(forge_engine::DemoSession::total(&p)>0).then(forge_engine::DemoSession::default),root:folder,level:1,menu:forge_engine::DemoSession::total(&p)>0,campaign,finished:false}).add_plugins(DefaultPlugins.set(AssetPlugin{file_path:root,..default()}).set(ImagePlugin::default_nearest()).set(WindowPlugin{primary_window:Some(Window{title:p.name.clone(),resolution:(p.settings.production.resolution[0] as f32,p.settings.production.resolution[1] as f32).into(),..default()}),..default()})).add_plugins(EguiPlugin::default()).init_resource::<HudInput>().add_systems(EguiPrimaryContextPass,hud).add_systems(Startup,setup).add_systems(Update,(tick,particle_render).chain()).run();}
fn setup(mut commands:Commands,game:Res<Game>,assets:Res<AssetServer>){commands.spawn(Camera2d);#[cfg(feature="audio")] for o in &game.project.objects{if let Some(s)=&o.pro.sound{if !s.path.starts_with("assets/"){continue;}let bus=if s.music{game.project.settings.music}else{game.project.settings.sfx};let volume=(s.volume*bus*game.project.settings.master).clamp(0.,1.);let settings=if s.looping{PlaybackSettings::LOOP}else{PlaybackSettings::DESPAWN};commands.spawn((AudioPlayer::new(assets.load::<AudioSource>(s.path.clone())),settings.with_volume(bevy::audio::Volume::Linear(volume))));}}for o in &game.project.objects{if o.camera{continue;}let mut sprite=Sprite::from_color(Color::srgba_u8(o.color[0],o.color[1],o.color[2],o.color[3]),Vec2::from_array(o.size));if let Some(path)=&o.sprite{sprite.image=assets.load(path.clone());}commands.spawn((sprite,Transform::default(),ObjectId(o.id)));}}
fn tick(mut commands:Commands,assets:Res<AssetServer>,time:Res<Time>,keys:Res<ButtonInput<KeyCode>>,pads:Query<&Gamepad>,hud:Res<HudInput>,mut game:ResMut<Game>,images:Res<Assets<Image>>,mut sprites:Query<(Entity,&ObjectId,&mut Transform,&mut Sprite),Without<Camera2d>>,mut cameras:Query<&mut Transform,With<Camera2d>>){let c=&game.project.settings.production.controls;let pressed=|s:&str,k|keys.pressed(forge_engine::keycode(s,k)) as i32;let mut d=[(pressed(&c.right,KeyCode::KeyD)-pressed(&c.left,KeyCode::KeyA)) as f32,(pressed(&c.up,KeyCode::KeyW)-pressed(&c.down,KeyCode::KeyS)) as f32];for pad in &pads{let dz=c.deadzone.clamp(0.,0.95);let axis=|a|{let v=pad.get(a).unwrap_or(0.);if v.abs()>dz{v}else{0.}};d[0]+=axis(GamepadAxis::LeftStickX);d[1]+=axis(GamepadAxis::LeftStickY);if pad.pressed(GamepadButton::South){d[1]=1.;}}for i in 0..2{d[i]=(d[i]+hud.0[i]).clamp(-1.,1.);}let g=&mut *game;if g.demo.is_some(){
 if keys.just_pressed(KeyCode::Escape){g.menu=!g.menu;}
 if hud.1 || keys.just_pressed(KeyCode::KeyR){g.project=g.original.clone();g.sim=Simulation::default();g.demo=Some(forge_engine::DemoSession::default());g.menu=false;g.finished=false;}
 if keys.just_pressed(KeyCode::Enter){g.menu=false;}
 if (hud.2 || keys.just_pressed(KeyCode::KeyN)) && g.demo.as_ref().is_some_and(|d|d.won){if g.campaign && g.level<3 {let next=g.level+1;match Project::load(&g.root.join(format!("level{next}.forge.json"))){Ok(p)=>{if let Err(e)=forge_engine::modules::validate(&p){eprintln!("{e}");return;}g.level=next;g.original=p.clone();g.project=p;g.sim=Simulation::default();g.demo=Some(forge_engine::DemoSession::default());g.menu=false;},Err(e)=>eprintln!("Level load: {e}")}}else{g.finished=true;}}
 }
 if !g.menu && !g.finished && !g.demo.as_ref().is_some_and(|x|x.won||x.health==0){let dt=time.delta_secs().min(0.033);g.sim.step(&mut g.project,dt,d);if let Some(demo)=&mut g.demo{let old=(demo.score(),demo.health,demo.won);demo.step(&mut g.project,dt);let cue=if demo.won&&!old.2{Some("win")}else if demo.health<old.1{Some("hurt")}else if demo.score()>old.0{Some("collect")}else{None};#[cfg(feature="audio")] if let Some(cue)=cue{let path=format!("assets/{cue}.wav");if g.root.join(&path).is_file(){commands.spawn((AudioPlayer::new(assets.load::<AudioSource>(path)),PlaybackSettings::DESPAWN.with_volume(bevy::audio::Volume::Linear((g.project.settings.master*g.project.settings.sfx).clamp(0.,1.)))));}}}}
 let objects:std::collections::HashMap<_,_>=g.project.objects.iter().filter(|o|!o.camera).map(|o|(o.id,o)).collect();let existing:std::collections::HashSet<_>=sprites.iter().map(|(_,id,_,_)|id.0).collect();
 for (entity,id,_,_) in &mut sprites{if !objects.contains_key(&id.0){commands.entity(entity).despawn();}}
 for o in &g.project.objects{if !o.camera&&!existing.contains(&o.id){let mut s=Sprite::from_color(Color::WHITE,Vec2::from_array(o.size));if let Some(path)=&o.sprite{s.image=assets.load(path.clone());}commands.spawn((s,Transform::default(),ObjectId(o.id)));}}for (_,id,mut t,mut s) in &mut sprites{if let Some(o)=objects.get(&id.0).copied(){s.custom_size=Some(Vec2::from_array(o.size));let c=forge_engine::lit_color(o,&g.project);s.color=Color::srgba_u8(c[0],c[1],c[2],c[3]);let p=forge_engine::sprite_center(o,g.project.isometric);t.translation=Vec3::new(p[0],p[1],o.layer as f32*10.+if g.project.isometric{-p[1]*0.001}else{0.});t.rotation=Quat::from_rotation_z(o.rotation.to_radians());if o.sprite.is_some(){if let Some(img)=images.get(&s.image){let uv=o.animation.uv(g.sim.elapsed);let size=img.size().as_vec2();s.rect=Some(Rect::from_corners(Vec2::from_array(uv[0])*size,Vec2::from_array(uv[2])*size));}}}}if let Some(o)=g.project.objects.iter().find(|o|o.camera){let p=project_point(o.position,g.project.isometric);for mut t in &mut cameras{t.translation.x=p[0];t.translation.y=p[1];}}}

#[derive(Component)] struct ParticleVisual;
fn particle_render(mut commands:Commands,game:Res<Game>,assets:Res<AssetServer>,mut old:Query<(Entity,&mut Sprite,&mut Transform),With<ParticleVisual>>){let mut pool=old.iter_mut();let mut count=0;for o in &game.project.objects{for (p,size,c) in forge_engine::particles(o,game.sim.elapsed){if count>=4096{break;}count+=1;let p=project_point(p,game.project.isometric);let mut sprite=Sprite::from_color(Color::srgba_u8(c[0],c[1],c[2],c[3]),Vec2::splat(size));if let Some(path)=&o.production.particle_texture{if path.starts_with("assets/"){sprite.image=assets.load(path.clone());}}let t=Transform::from_xyz(p[0],p[1],o.layer as f32*10.+1.);if let Some((_,mut s,mut tr))=pool.next(){*s=sprite;*tr=t;}else{commands.spawn((ParticleVisual,sprite,t));}}}for (e,_,_) in pool{commands.entity(e).despawn();}}

fn hud(mut contexts:EguiContexts,game:Res<Game>,mut input:ResMut<HudInput>){input.0=[0.;2];input.1=false;input.2=false;let Ok(ctx)=contexts.ctx_mut()else{return;};if let Some(d)=&game.demo{egui::Area::new(egui::Id::new("demo_hud")).fixed_pos(egui::pos2(24.,20.)).show(ctx,|ui|{egui::Frame::window(ui.style()).show(ui,|ui|{ui.heading("FORGE / SIGNAL LOST");ui.label(format!("ENERGY CORES  {} / {}",d.score(),forge_engine::DemoSession::total(&game.project)));ui.label(format!("SECTOR {}  |  HEALTH {} / 3",game.level,d.health));ui.label(if game.finished {"CAMPAIGN COMPLETE"}else if d.won {"SECTOR COMPLETE  |  N to continue"}else if d.health==0{"SIGNAL LOST  |  R to retry"}else{"A / D move · W jump · Esc menu"});if d.won&&!game.finished && ui.button("Continue").clicked(){input.2=true;}if d.health==0 && ui.button("Retry").clicked(){input.1=true;}});});if game.menu{egui::Window::new("SIGNAL LOST").anchor(egui::Align2::CENTER_CENTER,[0.,0.]).collapsible(false).resizable(false).show(ctx,|ui|{ui.heading("SIGNAL LOST / PRO");ui.label("Recover three energy cores and reach the exit.");if ui.button("Start / Restart sector").clicked(){input.1=true;}ui.label("Enter: resume  |  Esc: menu");});}}let rect=ctx.screen_rect();for (i,w) in game.project.settings.widgets.iter().enumerate(){let pos=rect.min+egui::vec2(rect.width()*w.anchor[0],rect.height()*w.anchor[1]);egui::Area::new(egui::Id::new(("hud",i))).fixed_pos(pos).show(ctx,|ui|{if w.action=="label"{ui.label(&w.text);}else{let r=ui.add_sized(w.size,egui::Button::new(&w.text));if r.is_pointer_button_down_on(){match w.action.as_str(){"left"=>input.0[0]-=1.,"right"=>input.0[0]+=1.,"jump"=>input.0[1]=1.,_=>{}}}}});}}
